<?php $page_title='Website Content';require 'includes/header.php';$keys=['store_name','store_email','store_phone','store_address','business_hours','hero_heading','hero_description','promo_text','footer_copyright'];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();foreach($keys as $k){$v=trim($_POST[$k]??'');$pdo->prepare("INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$k,$v]);}flash('success','Website content updated.');header('Location: content.php');exit;}$s=$pdo->query("SELECT setting_key,setting_value FROM site_settings");$settings=[];foreach($s as $r)$settings[$r['setting_key']]=$r['setting_value'];?>
<div class="page-head"><div><h1>Website Content</h1><p>Update key store copy without editing PHP.</p></div></div><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><?php foreach(['store_name'=>'Store Name','store_email'=>'Store Email','store_phone'=>'Store Phone','store_address'=>'Store Address','business_hours'=>'Business Hours'] as $k=>$label):?><div class="field"><label><?=$label?></label><input class="input" name="<?=$k?>" value="<?=e($settings[$k]??'')?>"></div><?php endforeach;?></div><?php foreach(['hero_heading'=>'Hero Heading','hero_description'=>'Hero Description','promo_text'=>'Promotional Banner','footer_copyright'=>'Footer Copyright'] as $k=>$label):?><div class="field"><label><?=$label?></label><textarea name="<?=$k?>" rows="3"><?=e($settings[$k]??'')?></textarea></div><?php endforeach;?><button class="btn">Save website content</button></form></div><?php require 'includes/footer.php';?>
